args.expression:
Array.from(document.querySelectorAll('[role=option]')).filter(o => o.textContent.includes('fwat3-n2 MTP Item A')).map(o => {
  const cells = o.querySelectorAll('*');
  return Array.from(cells).map(c => c.textContent?.trim()).filter(Boolean).join(' | ');
})

(() => {
  const supp = document.querySelector('input[name=supplier]');
  return {
    value: supp.value,
    ariaInvalid: supp.getAttribute('aria-invalid'),
    ariaExpanded: supp.getAttribute('aria-expanded'),
    hasDatalist: !!document.getElementById(supp.getAttribute('list'))
  };
})()

(() => {
  const supp = document.querySelector('input[name=supplier]');
  // Try pressing Enter to commit the typed value
  supp.focus();
  return 'focused';
})()

(() => {
  const supp = document.querySelector('input[name=supplier]');
  const expanded = supp.getAttribute('aria-expanded');
  const controls = supp.getAttribute('aria-controls');
  const listbox = controls ? document.getElementById(controls) : null;
  return {
    value: supp.value,
    expanded: expanded,
    controls: controls,
    listboxExists: !!listbox,
    listboxVisible: listbox && listbox.offsetParent !== null,
    listboxText: listbox ? listbox.textContent?.trim()?.substring(0, 200) : null
  };
})()

(() => {
  const opt = Array.from(document.querySelectorAll('[role=option]')).find(o => o.textContent.includes('fwat3-n2 MTP Item A'));
  const statusEl = opt.querySelector('[title*="Status"], [aria-label*="Status"]');
  return {
    statusTitle: statusEl?.getAttribute('title') || statusEl?.getAttribute('aria-label'),
    statusText: statusEl?.textContent?.trim(),
    markerLetter: statusEl?.querySelector('[class*=marker], [class*=badge]')?.textContent?.trim()
  };
})()

(() => {
  const opt = Array.from(document.querySelectorAll('[role=option]')).find(o => o.textContent.includes('fwat3-n2 MTP Item A'));
  const cells = opt.querySelectorAll('*');
  return Array.from(cells).map((c,i) => `${i}: [${c.tagName}] ${c.textContent?.trim()?.substring(0,40)}`).filter(Boolean).join('\n');
})()

(() => {
  const opt = Array.from(document.querySelectorAll('[role=option]')).find(o => o.textContent.includes('fwat3-n2 MTP Item A'));
  const spans = opt.querySelectorAll('span, [title], [aria-label]');
  const statusLike = Array.from(spans).filter(s => s.textContent?.includes('Status') || s.getAttribute('title')?.includes('Status') || s.getAttribute('aria-label')?.includes('Status'));
  return {statusSpans: statusLike.map(s => ({text: s.textContent, title: s.getAttribute('title'), ariaLabel: s.getAttribute('aria-label')}))};
})()

(() => {
  const opt = Array.from(document.querySelectorAll('[role=option]')).find(o => o.textContent.includes('fwat3-n2 MTP Item A'));
  return opt?.outerHTML?.substring(0, 2000);
})()
